"""Firing schedule model: segment definitions and temperature interpolation."""

from dataclasses import dataclass
from typing import List, Optional

import heatwork


@dataclass
class FiringSegment:
    name: str
    target_c: float
    rate_c_per_hr: Optional[float]
    hold_minutes: float = 0.0


class FiringSchedule:
    def __init__(self, start_c: float, segments: List[FiringSegment]):
        self.start_c = start_c
        self.segments = segments
        self._boundaries = self._build_boundaries()

    def _build_boundaries(self):
        """Compute (ramp_end, hold_end) elapsed seconds for each segment."""
        boundaries = []
        prev_c = self.start_c
        elapsed = 0.0
        for seg in self.segments:
            if seg.rate_c_per_hr:
                ramp_seconds = abs(seg.target_c - prev_c) / seg.rate_c_per_hr * 3600.0
            else:
                ramp_seconds = 0.0
            ramp_end = elapsed + ramp_seconds
            hold_end = ramp_end + seg.hold_minutes * 60.0
            boundaries.append((ramp_end, hold_end))
            elapsed = hold_end
            prev_c = seg.target_c
        return boundaries

    def total_duration(self) -> float:
        return self._boundaries[-1][1] if self._boundaries else 0.0

    def active_segment(self, elapsed: float) -> int:
        """Return the index of the segment covering `elapsed` seconds."""
        for i, (_, hold_end) in enumerate(self._boundaries):
            if elapsed <= hold_end:
                return i
        return len(self.segments) - 1

    def target_temperature(self, elapsed: float) -> float:
        idx = self.active_segment(elapsed)
        seg = self.segments[idx]
        ramp_end, hold_end = self._boundaries[idx]
        prev_c = self.start_c if idx == 0 else self.segments[idx - 1].target_c

        if elapsed >= ramp_end:
            return seg.target_c

        seg_start = self._boundaries[idx - 1][1] if idx > 0 else 0.0
        fraction = (elapsed - seg_start) / (ramp_end - seg_start)
        return prev_c + fraction * (seg.target_c - prev_c)

    def summarize_firing(self, samples):
        """Build the closing report for a completed simulation, via heatwork.evaluate."""
        return heatwork.evaluate(self, samples)
